// Generates AwareRemoteBundle.js, a single self-contained Scriptable script that
// inlines AwareSigning.js and AwareRemoteCore.js so users create ONE script
// instead of three. Source of truth stays in the individual modules.
//
// Run from the repository root:  node shortcut/build-bundle.mjs

import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));

function moduleBody(name) {
  const source = readFileSync(join(here, name), "utf8").trimEnd();
  if (!/module\.exports\s*=/.test(source)) {
    throw new Error(`${name} has no module.exports to inline`);
  }
  // Turn the CommonJS export into a value returned from an IIFE.
  return source.replace(/module\.exports\s*=/, "return");
}

const signing = moduleBody("AwareSigning.js");
const core = moduleBody("AwareRemoteCore.js");

const remote = readFileSync(join(here, "AwareRemote.js"), "utf8")
  .replace(/^\/\/[^\n]*\n/, "") // drop the original 3-file install comment
  .replace(/^const \{ sign \} = importModule\("AwareSigning"\);\n/m, "")
  .replace(/^const RemoteCore = importModule\("AwareRemoteCore"\);\n/m, "")
  .trimStart();

const bundle = `// AUTO-GENERATED by shortcut/build-bundle.mjs — do not edit directly.
// Single-file Scriptable bundle: paste this one file into a Scriptable script
// named "AwareRemote". Edit shortcut/*.js and re-run the build to regenerate.

const AwareSigning = (() => {
${signing}
})();
const { sign } = AwareSigning;

const RemoteCore = (() => {
${core}
})();

${remote}`;

const outPath = join(here, "AwareRemoteBundle.js");
writeFileSync(outPath, bundle);
console.log(`Wrote ${outPath} (${bundle.length} bytes)`);
